const lv_image_dsc_t *arcade_stage_car(int player){return player?&car_d_0:&car_d_1;}
static const lv_image_dsc_t *const palette[]={&stage_d_0,&stage_d_1,&stage_d_2,&stage_d_3,&stage_d_4,&stage_d_5,&stage_d_6,&stage_d_7,&stage_d_8,&stage_d_9,&stage_d_10,&stage_d_11,&stage_d_12,&stage_d_13,&stage_d_14,&stage_d_15,&stage_d_16,&stage_d_17};
const lv_image_dsc_t *arcade_stage_tile(int game,char symbol) {
    switch(game) {
    case 0: // Box Pusher: wood and stone walls
       if(symbol=='#')return palette[1];
       if(symbol==' ')return palette[0];
       break;
    case 1: // Garden mini-golf
       if(symbol=='#')return palette[3];
       if(symbol==' ')return palette[2];
       break;
    case 2:
       if(symbol=='O')return palette[6];
       if(symbol=='+')return palette[7];
       break;
    case 5:
       switch(symbol) {
       case 'A':case 'S':return palette[8];
       case 'D':return palette[9];
       case 'B':case 'b':return palette[10];
       case '!':return palette[11];
       case '+':return palette[12];
       case 'X':return palette[13];
       }
       break;
    case 6: // Crypt floor and stone wall
       if(symbol=='#')return palette[5];
       if(symbol==' ')return palette[4];
       break;
    }
    return NULL;
}
